    /**
     * Resolve which record this imported row maps to (generated custom logic).
     * @return  ?ProfilPelajar  Resolved record instance.
     */
    public function resolveRecord(): ?ProfilPelajar
    {
    
        $pelajar = Pelajar::firstWhere('nama_penuh', $this->data['pelajar'] ?? null);

        if (!$pelajar) {
            return null;
        }

        return ProfilPelajar::firstOrNew([
            'pelajar_id' => $pelajar->id
        ]);
    }

    /**
     * Notification body shown when the import finishes.
